WITH gaps AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY page ORDER BY event_time, id) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY page ORDER BY event_time, id) + INTERVAL 90 DAYS THEN 1 ELSE 0 END AS is_new_session FROM web_events), sessionized AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY page ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT id, session_id, event_type, event_time, duration_sec, session_no, CASE WHEN event_type RLIKE '^(click|search)$' THEN 'PRIORITY' WHEN event_type RLIKE '^(page_view|add_to_cart)$' THEN 'GROUP_A' ELSE 'OTHER_ZONE' END AS event_type_zone FROM sessionized;
